    public var review: String?
    /// The agent's screen, while it has one.
    public var screen: String?
    /// The same line the morning brief shows: "CI green · +41 -12 · screenshot".
    public var summary: String?

    public init(task: ShepTask, step: StepView, activity: String, live: Bool, checks: [CiCheck], stat: DiffStat, proof: [String], events: [TaskEvent], agent: AgentKind? = nil, branch: String? = nil, diff: String? = nil, review: String? = nil, screen: String? = nil, summary: String? = nil) {
        self.task = task
        self.step = step
        self.activity = activity
        self.live = live
        self.checks = checks
        self.stat = stat
        self.proof = proof
        self.events = events
        self.agent = agent
        self.branch = branch
        self.diff = diff
        self.review = review
        self.screen = screen
        self.summary = summary
    }

    enum CodingKeys: String, CodingKey {
        case task
        case step
        case activity
        case live
        case checks
        case stat
        case proof
        case events
        case agent
        case branch
        case diff
        case review
        case screen
        case summary
    }
}

