/// A reference to the task in its source, or the sentence the user typed.
public enum TaskSourceRef: Codable, Hashable, Sendable {
    case gitHubIssue(number: Int64, repo: String?)
    case linear(key: String)
    case jira(key: String)
    case notion(url: String)
    case monday(url: String)
    case slack(url: String)
    case sentence(text: String)
    /// A value from a newer daemon that this app does not know yet.
    case unknown(String)

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: AnyCodingKey.self)
        guard container.allKeys.count == 1, let key = container.allKeys.first else {
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "TaskSourceRef needs exactly one variant key"))
        }
        switch key.stringValue {
        case "GitHubIssue":
            let fields = try container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: key)
            self = .gitHubIssue(number: try fields.decode(Int64.self, forKey: AnyCodingKey("number")), repo: try fields.decodeIfPresent(String.self, forKey: AnyCodingKey("repo")))
        case "Linear":
            let fields = try container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: key)
            self = .linear(key: try fields.decode(String.self, forKey: AnyCodingKey("key")))
        case "Jira":
            let fields = try container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: key)
            self = .jira(key: try fields.decode(String.self, forKey: AnyCodingKey("key")))
        case "Notion":
            let fields = try container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: key)
            self = .notion(url: try fields.decode(String.self, forKey: AnyCodingKey("url")))
        case "Monday":
            let fields = try container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: key)
            self = .monday(url: try fields.decode(String.self, forKey: AnyCodingKey("url")))
        case "Slack":
            let fields = try container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: key)
            self = .slack(url: try fields.decode(String.self, forKey: AnyCodingKey("url")))
        case "Sentence":
            let fields = try container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: key)
            self = .sentence(text: try fields.decode(String.self, forKey: AnyCodingKey("text")))
        default:
            self = .unknown(key.stringValue)
        }
    }

    public func encode(to encoder: Encoder) throws {
        switch self {
        case let .gitHubIssue(number, repo):
            var container = encoder.container(keyedBy: AnyCodingKey.self)
            var fields = container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: AnyCodingKey("GitHubIssue"))
            try fields.encode(number, forKey: AnyCodingKey("number"))
            try fields.encodeIfPresent(repo, forKey: AnyCodingKey("repo"))
        case let .linear(key):
            var container = encoder.container(keyedBy: AnyCodingKey.self)
            var fields = container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: AnyCodingKey("Linear"))
            try fields.encode(key, forKey: AnyCodingKey("key"))
        case let .jira(key):
            var container = encoder.container(keyedBy: AnyCodingKey.self)
            var fields = container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: AnyCodingKey("Jira"))
            try fields.encode(key, forKey: AnyCodingKey("key"))
        case let .notion(url):
            var container = encoder.container(keyedBy: AnyCodingKey.self)
            var fields = container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: AnyCodingKey("Notion"))
            try fields.encode(url, forKey: AnyCodingKey("url"))
        case let .monday(url):
            var container = encoder.container(keyedBy: AnyCodingKey.self)
            var fields = container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: AnyCodingKey("Monday"))
            try fields.encode(url, forKey: AnyCodingKey("url"))
        case let .slack(url):
            var container = encoder.container(keyedBy: AnyCodingKey.self)
            var fields = container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: AnyCodingKey("Slack"))
            try fields.encode(url, forKey: AnyCodingKey("url"))
        case let .sentence(text):
            var container = encoder.container(keyedBy: AnyCodingKey.self)
            var fields = container.nestedContainer(keyedBy: AnyCodingKey.self, forKey: AnyCodingKey("Sentence"))
            try fields.encode(text, forKey: AnyCodingKey("text"))
        case let .unknown(tag):
            var container = encoder.singleValueContainer()
            try container.encode(tag)
        }
    }
}

/// The five states every task moves through, on every surface.
public enum TaskState: String, Codable, Hashable, Sendable, CaseIterable {
    case queued = "Queued"
    case working = "Working"
    case needsYou = "NeedsYou"
    case ready = "Ready"
    case merged = "Merged"
    /// A value from a newer daemon that this app does not know yet.
    case unknown = "__unknown__"

    public static var allCases: [TaskState] { [.queued, .working, .needsYou, .ready, .merged] }

    public init(from decoder: Decoder) throws {
        let raw = try decoder.singleValueContainer().decode(String.self)
        self = Self(rawValue: raw) ?? .unknown
    }
}

